function reverseLettersOnly(s: string): string {
  const isLetter = (c: string) => (c >= "a" && c <= "z") || (c >= "A" && c <= "Z");
  const stack: string[] = [];
  for (const c of s) if (isLetter(c)) stack.push(c);
  let out = "";
  for (const c of s) out += isLetter(c) ? stack.pop()! : c;
  return out;
}

