function reverseLettersOnly(s: string): string {
  const isLetter = (c: string) => (c >= "a" && c <= "z") || (c >= "A" && c <= "Z");
  const a = s.split("");
  let i = 0, j = a.length - 1;
  while (i < j) {
    if (!isLetter(a[i])) i++;
    else if (!isLetter(a[j])) j--;
    else {
      [a[i], a[j]] = [a[j], a[i]];
      i++;
      j--;
    }
  }
  return a.join("");
}

