class Solution:
    def reverseLettersOnly(self, s: str) -> str:
        a = list(s)
        is_letter = lambda c: "a" <= c <= "z" or "A" <= c <= "Z"
        i, j = 0, len(a) - 1
        while i < j:
            if not is_letter(a[i]):
                i += 1
            elif not is_letter(a[j]):
                j -= 1
            else:
                a[i], a[j] = a[j], a[i]
                i += 1
                j -= 1
        return "".join(a)

